from html import escape
import json

def header_html(path):
 items=[('/books/','本棚','BOOKS'),('/search/','さがす','SEARCH'),('/topics/','テーマから探す','TOPICS'),('/characters/','モチとシオ','CHARACTERS'),('/about/','このサイトについて','ABOUT'),('/contact/','お問い合わせ','CONTACT')]
 nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if path==p else '')+f'>{name}</a>' for p,name,_ in items)
 overlay=''.join(f'<a href="{p}" class="nav-dialog__link"><small>0{i}</small><span>{name}</span><em>{en}</em><b aria-hidden="true">↗</b></a>' for i,(p,name,en) in enumerate(items,1))
 return f'''<a class="skip" href="#main">本文へ移動</a><div class="scroll-progress" aria-hidden="true"></div><header class="site-header"><a class="brand" href="/" aria-label="もちとしおのニュース本棚 ホーム"><img class="brand__logo" src="/assets/logo.png" alt="もちとしお" width="1400" height="350"><small class="brand__caption">ニュースの本棚</small></a><nav class="site-nav" aria-label="メインナビゲーション">{nav}</nav><div class="header-controls"><button class="motion-toggle" type="button" aria-pressed="false" hidden><span aria-hidden="true">◉</span><span data-motion-label>動きを止める</span></button><button class="experience-menu" type="button" aria-haspopup="dialog" aria-controls="menu-dialog" hidden><span class="hamburger" aria-hidden="true"><i></i><i></i><i></i></span><span class="sr-only">メニュー</span></button></div></header><dialog class="nav-dialog" id="menu-dialog" aria-label="サイトメニュー"><div class="nav-dialog__top"><a href="/">もちとしお</a><button type="button" data-close-menu>閉じる ×</button></div><nav aria-label="全画面メニュー">{overlay}</nav><div class="nav-dialog__bottom"><a href="/guide/">サイトの使い方 →</a></div></dialog>'''

def footer_html():
 return '''<footer class="site-footer"><div class="footer-invitation"><img class="footer-character" src="/assets/icon.png" alt="" width="512" height="512" loading="lazy"><a href="/books/" class="footer-invitation__link"><span>本棚を見る</span><b aria-hidden="true">↗</b></a></div><div class="footer-info"><a class="brand" href="/"><img class="brand__logo" src="/assets/logo.png" alt="もちとしお" width="1400" height="350"><small class="brand__caption">ニュースの本棚</small></a><p class="footer-copy">ニュースを小さな本にまとめています。</p><nav class="footer-nav" aria-label="フッターナビゲーション"><a href="/books/">すべての本</a><a href="/search/">本をさがす</a><a href="/weeks/">週のまとめ</a><a href="/tags/">話題から探す</a><a href="/topics/">テーマから探す</a><a href="/characters/">モチとシオ</a><a href="/guide/">本棚の楽しみ方</a><a href="/about/">このサイトについて</a><a href="/sources/">参考記事一覧</a><a href="/editorial/">制作・掲載方針</a></nav></div><div class="footer-bottom"><span>© 2026 もちとしお</span><span><a href="/privacy/">プライバシーポリシー</a>　 <a href="/contact/">お問い合わせ</a>　 <a href="#top">ページ上部へ ↑</a></span></div></footer>'''

def hero_html(books):
 b=books[0];n=len(books);e=escape
 return f'''<section class="experience-hero" aria-labelledby="hero-heading"><div class="hero-kicker"><span>もちとしお</span><span>公開中：{n}冊</span></div><div class="hero-editorial"><img class="hero-character" src="/assets/icon.png" alt="もちとしお" width="512" height="512"><h1 id="hero-heading">ニュースの本棚</h1><p>毎日のニュースを小さな本にまとめています。<br>表紙を選ぶと、本文とあとがきを読めます。</p><a class="hero-enter magnetic" href="#shelf"><span>本を選ぶ</span><b aria-hidden="true">↘</b></a></div><div class="hero-stage" data-hero-stage><div class="stage-books" data-stage-books><img class="stage-ghost stage-ghost--back" src="/{books[2]['pages'][0]}" alt="" width="1367" height="1823" aria-hidden="true"><img class="stage-ghost stage-ghost--middle" src="/{books[1]['pages'][0]}" alt="" width="1367" height="1823" aria-hidden="true"><a class="stage-book" data-stage-link href="{b['url']}" aria-label="{e(b['title'])}を読む"><span class="stage-book__back" aria-hidden="true"></span><span class="stage-book__pages" aria-hidden="true"></span><span class="stage-book__spine" aria-hidden="true">もちとしお</span><span class="stage-book__front"><img data-stage-cover src="/{b['pages'][0]}" alt="{e(b['title'])}の表紙" width="1367" height="1823" fetchpriority="high"><span class="stage-book__shine" aria-hidden="true"></span></span></a></div><div class="stage-controls" hidden><button type="button" data-stage-prev aria-label="前の本">←</button><span data-stage-counter>01 / {n:02}</span><button type="button" data-stage-next aria-label="次の本">→</button><button type="button" class="stage-preview" data-stage-preview>表紙をひらく ↗</button></div><div class="stage-caption" aria-live="polite"><span data-stage-date>{b['date'].replace('-','.')}</span><strong data-stage-title>{e(b['title'])}</strong></div></div><div class="hero-bottom"><a href="/sources/">参考記事一覧 ↗</a><span class="scroll-cue">本棚へ <i aria-hidden="true">↓</i></span></div></section>'''

def extras_html(books):
 return '<div class="random-book"><a href="'+books[0]['url']+'" data-surprise>ランダムに一冊読む ↗</a></div>'

def dialogs_html(books):
 data=[{k:b[k] for k in ('id','title','date','url','pages')} for b in books]
 raw=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
 return f'''<script id="experience-books" type="application/json">{raw}</script><dialog class="book-dialog" id="book-dialog" aria-label="本を立ち読み"><div class="book-dialog__top"><span>立ち読み</span><button type="button" data-close-book>閉じる ×</button></div><div class="book-dialog__body"><div class="book-dialog__meta"><span data-preview-date></span><h2 data-preview-title></h2></div><div class="flip-stage"><div class="flipbook"><div class="flip-under" aria-hidden="true"><img data-flip-under alt=""></div><div class="flip-sheet"><img data-flip-current alt=""><div class="flip-sheet__shine" aria-hidden="true"></div></div></div></div><div class="book-dialog__controls"><button type="button" data-flip-prev aria-label="前のページ">←</button><span data-flip-counter aria-live="polite">1 / 4</span><button type="button" data-flip-next aria-label="次のページ">→</button></div><a class="book-dialog__details" data-preview-link href="{books[0]['url']}">本文・出典も読む ↗</a></div></dialog>'''
